adcs_vec3_t torque = {0};
uint32_t slew_mask = 0U;
double limit = 0.0;

if ((sa_input.enable != 0) && (sa_input.enable != 1)) cfg_valid = 0;
if ((sa_input.valid != 0) && (sa_input.valid != 1)) cfg_valid = 0;

if (cfg_valid) {
    if ((sa_config.enter_rad < 0.0) || (sa_config.enter_rad >= sa_config.exit_rad) ||
        (sa_config.exit_rad > ADCS_PI) ||
        (sa_config.acquire_gain_nm_rad < 0.0) || (sa_config.track_gain_nm_rad < 0.0) ||
        (sa_config.torque_limit_nm <= 0.0) || (sa_config.max_slew_nm_per_cycle <= 0.0) ||
        (sa_config.coast_decay < 0.0) || (sa_config.coast_decay > 1.0) ||
        (sa_config.acquire_samples < 1U) || (sa_config.acquire_samples > 20U) ||
        (sa_config.max_coast_samples < 1U) ||
        (sa_config.max_coast_samples >= sa_config.max_bad_samples) ||
        (sa_config.max_bad_samples > 20U))
        cfg_valid = 0;
}
if (cfg_valid) {
    if ((sa_config.enter_rad != sa_config.enter_rad) ||
        (sa_config.exit_rad != sa_config.exit_rad) ||
        (sa_config.acquire_gain_nm_rad != sa_config.acquire_gain_nm_rad) ||
        (sa_config.track_gain_nm_rad != sa_config.track_gain_nm_rad) ||
        (sa_config.torque_limit_nm != sa_config.torque_limit_nm) ||
        (sa_config.max_slew_nm_per_cycle != sa_config.max_slew_nm_per_cycle) ||
        (sa_config.coast_decay != sa_config.coast_decay))
        cfg_valid = 0;
}

if (!cfg_valid) sample_valid = 0;

if (sample_valid) {
    if ((sa_input.measured_body == NULL) || (sa_input.target_body == NULL)) sample_valid = 0;
}
if (sample_valid) {
    if ((!adcs_is_finite_vec3(sa_input.measured_body)) ||
        (!adcs_is_finite_vec3(sa_input.target_body)))
        sample_valid = 0;
}
if (sample_valid) {
    if ((adcs_vec3_norm(sa_input.measured_body) <= ADCS_EPS_NORM) ||
        (adcs_vec3_norm(sa_input.target_body) <= ADCS_EPS_NORM))
        sample_valid = 0;
}
if (sample_valid) {
    if ((adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &measured_unit) !=
         ADCS_OK) ||
        (adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &target_unit) != ADCS_OK))
        sample_valid = 0;
}

if (!sample_valid) {
    if (!sa_input.enable) {
        sa_state.mode = SA_OFF;
        sa_state.good_samples = 0U;
        sa_state.bad_samples = 0U;
        sa_state.coast_samples = 0U;
        sa_state.previous_torque_nm = (adcs_vec3_t){0, 0, 0};
        sa_output.mode = SA_OFF;
        sa_output.good_samples = 0U;
        sa_output.bad_samples = 0U;
        sa_output.coast_samples = 0U;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
        sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        sa_output.slew_mask = 0U;
        return;
    }

    sa_state.good_samples = 0U;
    sa_state.bad_samples++;
    if ((sa_state.mode == SA_TRACK) || (sa_state.mode == SA_COAST)) {
        if (sa_state.coast_samples < sa_config.max_coast_samples) {
            sa_state.mode = SA_COAST;
            sa_state.coast_samples++;
            sa_output.mode = SA_COAST;
            sa_output.good_samples = sa_state.good_samples;
            sa_output.bad_samples = sa_state.bad_samples;
            sa_output.coast_samples = sa_state.coast_samples;
            sa_output.error_rad = 0.0;
            sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
            sa_output.torque_nm =
                adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);
            sa_state.previous_torque_nm = sa_output.torque_nm;
            sa_output.slew_mask = 0U;
            return;
        } else {
            if (sa_state.bad_samples >= sa_config.max_bad_samples) {
                sa_state.mode = SA_FAULT;
            }
            sa_output.mode = sa_state.mode;
            sa_output.good_samples = sa_state.good_samples;
            sa_output.bad_samples = sa_state.bad_samples;
            sa_output.coast_samples = sa_state.coast_samples;
            sa_output.error_rad = 0.0;
            sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
            sa_output.torque_nm = sa_state.previous_torque_nm;
            sa_output.slew_mask = 0U;
            return;
        }
    } else {
        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_state.mode = SA_FAULT;
        }
        sa_output.mode = sa_state.mode;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
        sa_output.torque_nm = sa_state.previous_torque_nm;
        sa_output.slew_mask = 0U;
        return;
    }
}

if (!sa_input.enable) {
    sa_state.mode = SA_OFF;
    sa_state.good_samples = 0U;
    sa_state.bad_samples = 0U;
    sa_state.coast_samples = 0U;
    sa_state.previous_torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.mode = SA_OFF;
    sa_output.good_samples = 0U;
    sa_output.bad_samples = 0U;
    sa_output.coast_samples = 0U;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.slew_mask = 0U;
    return;
}

sa_state.bad_samples = 0U;

cross_mt = adcs_vec3_cross(&measured_unit, &target_unit);
dot_mt = adcs_vec3_dot(&measured_unit, &target_unit);
cross_norm = adcs_vec3_norm(&cross_mt);
angle = atan2(cross_norm, dot_mt);

if (cross_norm > ADCS_EPS_COLLINEAR) {
    axis = adcs_vec3_scale(&cross_mt, 1.0 / cross_norm);
} else {
    double ax_abs = fabs(measured_unit.x);
    double ay_abs = fabs(measured_unit.y);
    double az_abs = fabs(measured_unit.z);
    adcs_vec3_t basis;
    if ((ax_abs <= ay_abs) && (ax_abs <= az_abs)) {
        basis = (adcs_vec3_t){1, 0, 0};
    } else if (ay_abs <= az_abs) {
        basis = (adcs_vec3_t){0, 1, 0};
    } else {
        basis = (adcs_vec3_t){0, 0, 1};
    }
    axis = adcs_vec3_cross(&measured_unit, &basis);
    if (adcs_vec3_norm(&axis) <= ADCS_EPS_NORM) {
        if ((ax_abs <= ay_abs) && (ax_abs <= az_abs)) {
            if (ay_abs <= az_abs) {
                basis = (adcs_vec3_t){0, 1, 0};
            } else {
                basis = (adcs_vec3_t){0, 0, 1};
            }
        } else if (ay_abs <= az_abs) {
            if (ax_abs <= az_abs) {
                basis = (adcs_vec3_t){1, 0, 0};
            } else {
                basis = (adcs_vec3_t){0, 0, 1};
            }
        } else {
            if (ax_abs <= ay_abs) {
                basis = (adcs_vec3_t){1, 0, 0};
            } else {
                basis = (adcs_vec3_t){0, 1, 0};
            }
        }
        axis = adcs_vec3_cross(&measured_unit, &basis);
    }
    axis = adcs_vec3_scale(&axis, 1.0 / adcs_vec3_norm(&axis));
}

next_mode = sa_state.mode;
if (next_mode == SA_OFF) next_mode = SA_SEARCH;

if (next_mode == SA_SEARCH) {
    if (angle <= sa_config.enter_rad) {
        next_mode = SA_ACQUIRE;
        sa_state.good_samples = 1U;
    }
} else if (next_mode == SA_ACQUIRE) {
    if (angle <= sa_config.enter_rad) {
        sa_state.good_samples++;
        if (sa_state.good_samples >= sa_config.acquire_samples) {
            next_mode = SA_TRACK;
        }
    } else {
        next_mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    }
} else if (next_mode == SA_TRACK) {
    if (angle >= sa_config.exit_rad) {
        next_mode = SA_SEARCH;
    }
} else if (next_mode == SA_COAST) {
    if (angle < sa_config.exit_rad) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
    sa_state.coast_samples = 0U;
} else {
    next_mode = sa_state.mode;
}

sa_state.mode = next_mode;
if (next_mode == SA_TRACK) {
    gain = sa_config.track_gain_nm_rad;
} else {
    gain = sa_config.acquire_gain_nm_rad;
}

torque = adcs_vec3_scale(&axis, -gain * angle);
limit = adcs_vec3_norm(&torque);
if (limit > sa_config.torque_limit_nm) {
    torque = adcs_vec3_scale(&torque, sa_config.torque_limit_nm / limit);
}

{
    double comp[3] = {torque.x, torque.y, torque.z};
    double prev[3] = {sa_state.previous_torque_nm.x, sa_state.previous_torque_nm.y,
                      sa_state.previous_torque_nm.z};
    for (i = 0U; i < 3U; i++) {
        double d = comp[i] - prev[i];
        if (d > sa_config.max_slew_nm_per_cycle) {
            comp[i] = prev[i] + sa_config.max_slew_nm_per_cycle;
            slew_mask |= (1U << i);
        } else if (d < -sa_config.max_slew_nm_per_cycle) {
            comp[i] = prev[i] - sa_config.max_slew_nm_per_cycle;
            slew_mask |= (1U << i);
        } else {
            comp[i] = comp[i];
        }
    }
    torque = (adcs_vec3_t){comp[0], comp[1], comp[2]};
}

sa_state.previous_torque_nm = torque;
sa_output.mode = sa_state.mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;
sa_output.torque_nm = torque;
sa_output.slew_mask = slew_mask;

