sa_input_t *in = &sa_input;
sa_config_t *cfg = &sa_config;
sa_state_t *st = &sa_state;
sa_output_t *out = &sa_output;
int rejected = 0;
int cfg_ok = 1;
adcs_vec3_t measured, target, axis;
double dot = 0.0, cross_norm = 0.0, angle = 0.0;

/* 配置校验 */
if ((in->enable != 0 && in->enable != 1) ||
    (in->valid != 0 && in->valid != 1) ||
    !(cfg->enter_rad >= 0.0 && cfg->enter_rad < cfg->exit_rad && cfg->exit_rad <= ADCS_PI) ||
    !(cfg->acquire_gain_nm_rad >= 0.0) ||
    !(cfg->track_gain_nm_rad >= 0.0) ||
    !(cfg->torque_limit_nm > 0.0) ||
    !(cfg->max_slew_nm_per_cycle > 0.0) ||
    !(cfg->coast_decay >= 0.0 && cfg->coast_decay <= 1.0) ||
    !(cfg->acquire_samples >= 1U && cfg->acquire_samples <= 20U) ||
    !(cfg->max_coast_samples >= 1U && cfg->max_coast_samples < cfg->max_bad_samples) ||
    !(cfg->max_bad_samples <= 20U))
    cfg_ok = 0;

/* 样本有效性 */
if ((in->measured_body == NULL) || (in->target_body == NULL) ||
    !adcs_is_finite_vec3(in->measured_body) || !adcs_is_finite_vec3(in->target_body))
    rejected = 1;
if (cfg_ok == 0) rejected = 1;
if (in->valid == 0) rejected = 1;

if (rejected == 0) {
    if (adcs_vec3_normalize(in->measured_body, 0.0, &measured) != ADCS_OK) rejected = 1;
    if (rejected == 0 && adcs_vec3_normalize(in->target_body, 0.0, &target) != ADCS_OK) rejected = 1;
}

if (rejected == 0) {
    adcs_vec3_t cross, basis;
    double ax, ay, az;
    dot = adcs_vec3_dot(&measured, &target);
    cross = adcs_vec3_cross(&measured, &target);
    cross_norm = adcs_vec3_norm(&cross);
    angle = atan2(cross_norm, dot);
    if (cross_norm <= ADCS_EPS_NORM && dot < 0.0) {
        /* 反平行：选最不共线的笛卡尔基，按 x,y,z 顺序打破平局 */
        ax = fabs(measured.x);
        ay = fabs(measured.y);
        az = fabs(measured.z);
        if (ax <= ay && ax <= az) {
            basis = (adcs_vec3_t){1.0, 0.0, 0.0};
        } else if (ay <= az) {
            basis = (adcs_vec3_t){0.0, 1.0, 0.0};
        } else {
            basis = (adcs_vec3_t){0.0, 0.0, 1.0};
        }
        cross = adcs_vec3_cross(&measured, &basis);
        if (adcs_vec3_normalize(&cross, 0.0, &axis) != ADCS_OK) {
            axis = (adcs_vec3_t){1.0, 0.0, 0.0};
        }
        angle = ADCS_PI;
    } else if (cross_norm <= ADCS_EPS_NORM) {
        /* 平行同向：无旋转 */
        axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        angle = 0.0;
    } else {
        axis = adcs_vec3_scale(&cross, 1.0 / cross_norm);
    }
}

if (rejected) {
    sa_mode_t prev_mode = st->mode;
    st->good_samples = 0;
    st->bad_samples++;

    /* 只有配置有效时才允许吸收进 COAST */
    if (cfg_ok != 0 && (prev_mode == SA_TRACK || prev_mode == SA_COAST) &&
        st->coast_samples < cfg->max_coast_samples) {
        st->mode = SA_COAST;
        st->coast_samples++;
        out->torque_nm = adcs_vec3_scale(&st->previous_torque_nm, cfg->coast_decay);
        out->slew_mask = 0U;
        out->rotation_axis = (adcs_vec3_t){0, 0, 0};
        out->error_rad = 0.0;
        st->previous_torque_nm = out->torque_nm;
    } else {
        if (prev_mode == SA_TRACK || prev_mode == SA_COAST) {
            /* 超出 coast 允许：不吸收，保留当前 mode */
            out->torque_nm = st->previous_torque_nm;
            out->slew_mask = 0U;
            out->rotation_axis = (adcs_vec3_t){0, 0, 0};
            out->error_rad = 0.0;
        } else {
            out->torque_nm = st->previous_torque_nm;
            out->slew_mask = 0U;
            out->rotation_axis = (adcs_vec3_t){0, 0, 0};
            out->error_rad = 0.0;
        }
        if (st->bad_samples >= cfg->max_bad_samples) st->mode = SA_FAULT;
    }

    out->mode = st->mode;
    out->good_samples = st->good_samples;
    out->bad_samples = st->bad_samples;
    out->coast_samples = st->coast_samples;
} else {
    st->bad_samples = 0;

    if (in->enable == 0) {
        st->mode = SA_OFF;
        st->good_samples = 0;
        st->coast_samples = 0;
        st->previous_torque_nm = (adcs_vec3_t){0, 0, 0};
        out->mode = SA_OFF;
        out->good_samples = 0;
        out->bad_samples = 0;
        out->coast_samples = 0;
        out->error_rad = 0.0;
        out->rotation_axis = (adcs_vec3_t){0, 0, 0};
        out->torque_nm = (adcs_vec3_t){0, 0, 0};
        out->slew_mask = 0U;
    } else {
        sa_mode_t start = (st->mode == SA_OFF) ? SA_SEARCH : st->mode;

        if (start == SA_SEARCH) {
            if (angle <= cfg->enter_rad) {
                st->mode = SA_ACQUIRE;
                st->good_samples = 1U;
            } else {
                st->mode = SA_SEARCH;
            }
        } else if (start == SA_ACQUIRE) {
            if (angle <= cfg->enter_rad) {
                st->good_samples++;
                if (st->good_samples >= cfg->acquire_samples) {
                    st->mode = SA_TRACK;
                } else {
                    st->mode = SA_ACQUIRE;
                }
            } else {
                st->mode = SA_SEARCH;
                st->good_samples = 0;
            }
        } else if (start == SA_TRACK) {
            if (angle >= cfg->exit_rad) {
                st->mode = SA_SEARCH;
                st->good_samples = 0;
            } else {
                st->mode = SA_TRACK;
            }
        } else if (start == SA_COAST) {
            st->coast_samples = 0;
            if (angle < cfg->exit_rad) {
                st->mode = SA_TRACK;
            } else {
                st->mode = SA_SEARCH;
            }
        } else {
            st->mode = SA_SEARCH;
        }

        if (st->mode == SA_TRACK) {
            out->torque_nm = adcs_vec3_scale(&axis, cfg->track_gain_nm_rad * angle);
        } else {
            out->torque_nm = adcs_vec3_scale(&axis, cfg->acquire_gain_nm_rad * angle);
        }

        {
            double n = adcs_vec3_norm(&out->torque_nm);
            if (n > cfg->torque_limit_nm && n > 0.0) {
                out->torque_nm = adcs_vec3_scale(&out->torque_nm, cfg->torque_limit_nm / n);
            }
        }

        out->slew_mask = 0U;
        {
            adcs_vec3_t lim = out->torque_nm;
            double d;
            d = lim.x - st->previous_torque_nm.x;
            if (d > cfg->max_slew_nm_per_cycle) {
                lim.x = st->previous_torque_nm.x + cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 1U;
            } else if (d < -cfg->max_slew_nm_per_cycle) {
                lim.x = st->previous_torque_nm.x - cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 1U;
            }
            d = lim.y - st->previous_torque_nm.y;
            if (d > cfg->max_slew_nm_per_cycle) {
                lim.y = st->previous_torque_nm.y + cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 2U;
            } else if (d < -cfg->max_slew_nm_per_cycle) {
                lim.y = st->previous_torque_nm.y - cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 2U;
            }
            d = lim.z - st->previous_torque_nm.z;
            if (d > cfg->max_slew_nm_per_cycle) {
                lim.z = st->previous_torque_nm.z + cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 4U;
            } else if (d < -cfg->max_slew_nm_per_cycle) {
                lim.z = st->previous_torque_nm.z - cfg->max_slew_nm_per_cycle;
                out->slew_mask |= 4U;
            }
            out->torque_nm = lim;
        }

        out->mode = st->mode;
        out->good_samples = st->good_samples;
        out->bad_samples = st->bad_samples;
        out->coast_samples = st->coast_samples;
        out->error_rad = angle;
        out->rotation_axis = axis;

        st->previous_torque_nm = out->torque_nm;
    }
}

